from pathlib import Path
import re, html, csv
root=Path('output/poster-narrative-3/layout-v4')
old=Path('output/poster-narrative-3/poster/index.html').read_text()
icons=re.search(r'<svg class="icon-defs".*?</svg>',old,re.S).group()
def p(s,cls=''):return f'<p class="{cls}">{s}</p>'
def section(n,title,body,cls=''):return f'<section id="s{n}" class="{cls}"><h2><span>{n}.</span> {title}</h2><div class="content">{body}</div></section>'
left=section(1,'Research Context',p('RAG grounds language-model answers in external documents, but legal QA requires a pipeline to satisfy two goals at once: retrieve enough relevant evidence to produce a correct answer, while keeping source-page citations precise and complete. This is challenging because legal PDFs may lack machine-readable text, evidence can appear at different textual scales, and questions may depend on either exact legal references or semantic similarity. Moreover, retrieving more evidence can improve coverage while also introducing irrelevant source pages. We therefore examine how design choices in document processing, retrieval, and attribution can improve answer quality without sacrificing citation quality.'))
left+=section(2,'Prior Work &amp; Study Focus',p('Retrieval-augmented generation (RAG) conditions language-model answers on retrieved documents [1]. Legal retrieval must balance precision and coverage: LegalBench-RAG targets minimal relevant passages [2], while regulatory QA studies show that retrieving all supporting evidence becomes harder when it spans multiple passages [3]. In an end-to-end legal benchmark, retrieval-model choice had a larger effect on answer correctness than generator choice [4].')+p('Evaluation also extends beyond correctness. Legal QA research examines whether answers are supported by the supplied context [5], while ALCE evaluates answer correctness and citation quality separately [6]. Together, these studies motivate evaluating both the evidence available to the generator and the sources ultimately cited.')+p('Our study complements these approaches by holding the generator fixed and examining a broader sequence of pipeline choices, from document processing to final page selection.'))
left+=section(3,'Research question',p('With the answer generator fixed, which pipeline additions improve answer quality and page-level citation precision and recall, and where do these objectives conflict?'),'question')
left+=section(4,'Our Contribution',p('We build a Legal RAG pipeline and provide an empirical comparison of seven cumulative configurations on 30 documents and 100 questions. By adding components sequentially while keeping the answer generator fixed, we measure changes in answer quality and page-level citation precision and recall across stages of document processing, retrieval, reranking, answer processing, and citation selection.'))
hyps=[('H1 — Retrieval','Combining multiple text granularities, semantic and lexical retrieval, and relevance reranking will improve answer quality and evidence retrieval compared with a simple semantic-retrieval baseline.'),('H2 — Robustness to scanned documents','Recovering text from scan-like legal documents will reduce the performance loss caused by the absence of a machine-readable text layer.'),('H3 — Citation attribution','Selecting source pages after answer generation will produce a more focused citation set without substantially reducing the coverage of relevant evidence.')]
left+=section(5,'Hypothesis',''.join(f'<div class="hyp h{i+1}"><h3>{a}</h3>{p(b)}</div>' for i,(a,b) in enumerate(hyps)))

data='<h3>Data</h3>'+p('30 DIFC legal PDFs (590 pages), 100 questions, including 70 structured-answer and 30 free-text questions. Reference source pages are available for 95 questions. For the scan-robustness test, 10 of the 30 documents (107 pages) were converted into synthetic scans: each page was rasterised as an image and its machine-readable text layer was removed.')
data+='<h3 class="subhead">Pipeline</h3>'+p('Starting from a simple baseline, we add one capability at a time. Each variant includes all previous additions.')
def icon(i):return f'<svg class="icon" aria-hidden="true"><use href="#icon-{i}"/></svg>'
data+='<div class="baseline"><h3>R0 · Baseline</h3><div class="flow">'+''.join(f'<div>{icon(i)}<strong>{s}</strong></div>' for i,s in [('file','PDF text<br><span>300-token passages</span>'),('search','Semantic retrieval'),('answer','GPT-5.4-mini'),('file','Answer +<br>retrieved pages')])+'</div>'+p('Dense retrieval: Qwen3-Embedding-0.6B','dense')+'</div>'
cards=[('doc','R1 · Read scans','Convert scanned pages into searchable text','PP-OCRv5','scan'),('doc','R2 · Represent evidence at multiple scales','','Pages · sections · clauses · microchunks · tables','layers'),('retr','R3 · Find exact terms too','Combine semantic and exact-word search','BM25 + RRF','search'),('retr','R4 · Prioritize better evidence','Move the most relevant passages to the top','Qwen3-Reranker','rank'),('ans','R5 · Check the answer','Normalize and validate the expected answer type','Typed schema','check'),('cit','R6 · Refine citations','Keep only pages that support the final answer','Supporting-chunk references','link')]
data+='<div class="stages"><div class="phase doc">Document processing</div><div class="phase retr">Retrieval</div><div class="phase ans single">Answering</div><div class="phase cit single">Citations</div>'
for c,t,desc,tech,i in cards:
 data+=f'<div class="stage {c}"><h3>{t}</h3>'+p(desc)+icon(i)+p(tech,'tech')+'</div>'
data+='</div>'+p('<strong>Answer generation:</strong> A fixed GPT-5.4-mini configuration is used across variants, so changes in performance reflect modifications to the surrounding pipeline rather than a change of the generating LLM.','fixed')
center=section(6,'Data and Methods <span class="method-label">/ Methodology</span>',data)
ev=p('A correct answer does not necessarily imply good citations. A system may produce the right answer while citing irrelevant pages, or it may cite only part of the evidence required to support the answer. We therefore evaluate answer quality and citation quality separately.','eval-intro')
ev+='<div class="eval-grid">'
for c,t,q,d in [('doc','Answer quality','Is the generated answer correct?','<strong>Q = 0.7 × structured score<br>+ 0.3 × free-text score</strong>'),('retr','Citation precision','Are the cited pages actually relevant?','Share of cited pages that support the answer.'),('ans','Citation recall','Did the system cite all required evidence?','Share of annotated supporting pages that were cited.')]:
 ev+=f'<div class="{c}"><h3>{t}</h3>{p(q,"metric-question")}{p(d)}</div>'
ev+='</div>'
center+=section(7,'Evaluation',ev)
con=p('Legal RAG should be designed as a multi-stage pipeline: OCR improves robustness to unreadable PDFs, hybrid retrieval and reranking improve answer quality, and post-answer citation selection improves citation precision. However, citation selection introduces a precision–recall trade-off, so answer quality and citation quality should be optimized and evaluated separately.','main-takeaway')
con+='<div class="takeaways">'
for t,b in [('1 · Ensure document robustness','OCR provides robustness when machine-readable text is unavailable. It recovered most of the performance loss introduced by synthetic scans.'),('2 · Optimize retrieval','Hybrid retrieval and reranking produced the largest observed gains in answer quality. Additional representation complexity did not consistently improve performance.'),('3 · Optimize citations separately','Post-answer citation selection substantially increased precision, with a small reduction in recall.')]:con+=f'<div><h3>{t}</h3>{p(b)}</div>'
con+='</div>'+p('<strong>Unexpected outcome:</strong> Multi-scale representations did not improve performance; Q decreased from 63.2% to 49.8% after R2.','unexpected')
center+=section(11,'Conclusion and takeaways',con,'conclusion')

# Keep the previous three-panel line chart, rebuilding its vector geometry for this column.
rows=list(csv.DictReader(open('output/poster-narrative-3/results/metrics.csv')))
mixed=[r for r in rows if r['corpus']=='mixed']
def txt(x,y,s,cls='',anchor='start'):return f'<text x="{x}" y="{y}" class="{cls}" text-anchor="{anchor}">{html.escape(str(s))}</text>'
svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 375" class="chart" role="img" aria-label="Answer quality, citation precision and citation recall across R0 to R6"><style>text{font-family:Poster,sans-serif;font-size:26px;fill:#13304c}.ctitle{font-weight:bold;font-size:30px}.val{font-weight:bold;font-size:25px;paint-order:stroke;stroke:#fff;stroke-width:5px;stroke-linejoin:round}.axis{fill:#516578;font-size:24px}</style>'
for k,(key,title,n) in enumerate([('Q','Answer quality Q, %','100 questions'),('precision','Citation precision, %','95 questions'),('recall','Citation recall, %','95 questions')]):
 x=k*323
 svg+=txt(x+4,31,title,'ctitle')+txt(x+4,66,n,'axis')
 x0=x+40;x1=x+292;yt=117;yb=314
 for tick in [0,50,100]:
  y=yb-(yb-yt)*tick/100
  svg+=f'<path d="M{x0} {y}H{x1+8}" stroke="#dce6ed" stroke-width="1.5"/>'+txt(x0-9,y+8,tick,'axis','end')
 pts=[(x0+i*(x1-x0)/6,yb-(yb-yt)*float(r[key])) for i,r in enumerate(mixed)]
 svg+=f'<polyline points="{" ".join(f"{a},{b}" for a,b in pts)}" fill="none" stroke="#0674b6" stroke-width="4"/>'
 for i,((a,b),r) in enumerate(zip(pts,mixed)):
  offset=31 if (key in ['Q','recall'] and i==2) or (key=='precision' and i==5) else -18
  svg+=f'<circle cx="{a}" cy="{b}" r="5" fill="#0674b6"/>'+txt(a,b+offset,f'{float(r[key])*100:.1f}','val','middle')+txt(a,354,r['variant'],'axis','middle')
svg+='</svg>'
right=section(8,'Results',svg)
ocr='<h3>OCR recovers performance on scanned documents</h3><div class="ocr-bars">'
for label,value in [('Original corpus · R0',65.4),('Mixed corpus (original + synthetic scans) · R0',46.2),('Mixed corpus + OCR · R1',63.2)]:
 ocr+=f'<div class="bar-row"><span>{label}</span><div class="track"><div class="bar" style="width:{value}%"></div><strong style="left:calc({value}% + 8px)">{value}</strong></div></div>'
ocr+='<div class="scale"><span>0</span><span>50</span><span>100%</span></div></div>'+p('Converting 10 documents into synthetic scans reduces answer quality from 65.4% to 46.2%. OCR restores most of this loss, reaching 63.2%.')
right+=section(9,'OCR robustness',ocr)
evals=[('H1 — Retrieval &amp; representation','Partially supported.','Multi-scale representations alone reduce Q, but adding lexical retrieval and reranking substantially improves answer quality and source-page recall.'),('H2 — Scan robustness','Supported.','OCR restores most of the answer-quality loss caused by removing the machine-readable text layer.'),('H3 — Citation selection','Supported with a trade-off.','Precision rises from 27.1% to 61.8%, while recall decreases moderately from 78.9% to 74.7%.')]
right+=section(10,'Hypothesis evaluation',''.join(f'<div class="hyp-result h{i+1}"><h3>{t}</h3>{p(f"<strong>{s}</strong> {b}")}</div>' for i,(t,s,b) in enumerate(evals)))
right+=section(12,'Limitations',p('one DIFC corpus and 100 questions; one run per condition with no significance testing; LLM-based evaluation of free-text answers.'))
refs=[('Lewis, P., Perez, E., Piktus, A., Petroni, F., Karpukhin, V., Goyal, N., ... &amp; Kiela, D. (2020). Retrieval-augmented generation for knowledge-intensive nlp tasks. Advances in neural information processing systems, 33, 9459-9474.'),('Pipitone, Nicholas, and Ghita Houir Alami. "Legalbench-rag: A benchmark for retrieval-augmented generation in the legal domain." arXiv preprint arXiv:2408.10343 (2024).'),('Gokhan, T., &amp; Briscoe, T. (2025, November). Grounded Answers from Multi-Passage Regulations: Learning-to-Rank for Regulatory RAG. In Proceedings of the Natural Legal Language Processing Workshop 2025 (pp. 135-146).'),('Butler, A. R., &amp; Butler, U. (2026). Legal RAG Bench: an end-to-end benchmark for legal RAG. arXiv preprint arXiv:2603.01710.'),('Trautmann, D., Ostapuk, N., Grail, Q., Pol, A., Bonifazi, G., Gao, S., &amp; Gajek, M. (2024, November). Measuring the groundedness of legal question-answering systems. In Proceedings of the Natural Legal Language Processing Workshop 2024 (pp. 176-186).'),('Gao, T., Yen, H., Yu, J., &amp; Chen, D. (2023, December). Enabling large language models to generate text with citations. In Proceedings of the 2023 Conference on Empirical Methods in Natural Language Processing (pp. 6465-6488).')]
right+=section(13,'References', '<ol>'+''.join(f'<li>{r}</li>' for r in refs)+'</ol>'+p('<strong>Code, protocol &amp; results</strong><br><a href="https://github.com/SteinVR/Trends-in-NLP-Poster">github.com/SteinVR/Trends-in-NLP-Poster</a>','code'))
css='''
@font-face{font-family:Poster;src:url('assets/NimbusSansNarrow-Regular.otf');font-weight:400}
@font-face{font-family:Poster;src:url('assets/NimbusSansNarrow-Bold.otf');font-weight:700}
*{box-sizing:border-box}html,body{margin:0;padding:0}body{background:#dae5ec;color:#18334a;font-family:Poster,sans-serif;font-size:24pt;line-height:1.1}
.poster{width:841mm;height:594mm;background:white;padding:9mm 10mm 9mm;margin:20px auto;box-shadow:0 8px 40px #16364a30;display:flex;flex-direction:column}
p,h1,h2,h3{margin:0}p+p{margin-top:12px}h1{font-size:52pt;line-height:1.03;color:#082b51;letter-spacing:-.4px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #a8cbdc;padding:0 10px 22px;gap:38px;margin-bottom:22px}.logo{width:350px;height:auto}.columns{display:grid;grid-template-columns:27% 42% 1fr;gap:22px;flex:1;min-height:0}.col{display:flex;flex-direction:column;gap:18px;min-width:0}
section{break-inside:avoid;min-width:0}h2{background:linear-gradient(90deg,#056097,#0071ae);color:#fff;border-radius:6px 6px 0 0;font-size:29pt;line-height:1.08;padding:9px 17px 8px;font-weight:700;letter-spacing:.15px}h2>span{margin-right:7px}.content{background:#f2f8fc;border:1px solid #d9e9f1;border-radius:0 0 9px 9px;padding:17px 19px}h3{font-size:25pt;color:#073c64;line-height:1.08;margin-bottom:6px}.method-label{font-size:24pt;font-weight:400;opacity:.9}.question .content{background:#eaf5fc;text-align:center;font-weight:700;color:#082f56;padding:20px 24px;font-size:26pt;line-height:1.1}
#s5 .content{padding:0;border:none;background:white}.hyp{padding:13px 17px;margin-top:8px;border-radius:8px}.h1{background:#eaf4fb}.h2{background:#eff7e9}.h3{background:#f2ebfa}.subhead{margin-top:20px}.baseline{margin:19px 0 23px;background:#e6f3fb;border:1px solid #cfdfeb;border-radius:8px;padding:16px}.baseline>h3{margin-bottom:14px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:35px}.flow>div{display:flex;align-items:center;gap:12px;position:relative}.flow>div:not(:last-child)::after{content:'→';position:absolute;right:-31px;font-size:38px;color:#427a9c}.flow strong{line-height:1.1}.flow span{font-weight:400}.dense{margin-top:15px;color:#345c73}.icon-defs{position:absolute;width:0;height:0;overflow:hidden}.icon{width:66px;height:66px;flex:none;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.stages{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.phase{grid-column:span 2;text-align:center;font-weight:700;font-size:23pt;text-transform:uppercase;padding:12px 5px;border-radius:6px}.phase.single{grid-column:span 1}.doc{background:#eaf5fc;--stage:#147ba7}.retr{background:#eef7e9;--stage:#3b782d}.ans{background:#fff1e5;--stage:#ab5826}.cit{background:#f1eafb;--stage:#6845a0}.stage{padding:15px 13px;border-radius:8px;display:flex;flex-direction:column;position:relative;min-height:398px;border:1px solid #d8e4ec}.stage h3{font-size:25pt;min-height:116px;color:var(--stage)}.stage p{line-height:1.09}.stage .icon{color:var(--stage);margin:20px auto}.stage .tech{margin-top:auto;padding-top:14px;border-top:1px solid #c8d8e2}.stage:not(:last-child)::after{content:'→';position:absolute;right:-14px;top:48%;color:var(--stage);font-size:29px;z-index:1}.fixed{margin-top:19px;padding-top:16px;border-top:1px solid #cbdde7}
.eval-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-top:18px}.eval-grid>div{padding:16px;border-radius:7px}.metric-question{font-style:italic;margin:10px 0 14px}.main-takeaway{background:#075c91;color:white;border-radius:8px;padding:20px 23px;line-height:1.12}.takeaways{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:20px}.takeaways>div+div{border-left:1px solid #c8dce7;padding-left:20px}.takeaways h3{margin-bottom:10px}.unexpected{margin-top:18px!important;border-top:1px solid #c8dce7;padding-top:14px}.conclusion{margin-top:auto}
.chart{width:100%;display:block}.ocr-bars{margin:17px 0 19px}.bar-row{margin-bottom:13px}.bar-row>span{display:block;margin-bottom:6px}.track{position:relative;background:#e4edf3;height:25px;width:91%}.bar{height:100%;background:#087ab9}.track strong{position:absolute;top:-4px;font-size:25pt;white-space:nowrap}.scale{width:91%;display:flex;justify-content:space-between;font-size:21pt;color:#476579;margin-top:6px}.hyp-result{display:grid;grid-template-columns:26% 1fr;gap:16px;padding:15px;border-radius:7px;margin-bottom:10px}.hyp-result:last-child{margin-bottom:0}.hyp-result h3{font-size:24pt}.hyp-result p{line-height:1.09}#s10 .content{padding:12px;background:#fff}.right{gap:16px}#s13{margin-top:auto}#s13 .content{background:#f8fbfd}ol{margin:0;padding-left:32px}li{padding-left:4px;margin-bottom:9px;font-size:20pt;line-height:1.06}li:last-child{margin-bottom:0}.code{font-size:22pt;margin-top:15px;padding-top:11px;border-top:1px solid #c8dce7}a{color:#075a8b;text-decoration:none}
@page{size:841mm 594mm;margin:0}@media print{html,body{width:841mm;height:594mm;background:white}.poster{margin:0;box-shadow:none;zoom:1!important}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''
(root/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Building Legal RAG — Layout v4</title><style>'+css+'</style></head><body>'+icons+'<main class="poster"><header><h1>Building Legal RAG:<br>what each component contributes</h1><img class="logo" src="assets/trier-university.svg" alt="Universität Trier"></header><div class="columns"><div class="col left">'+left+'</div><div class="col center">'+center+'</div><div class="col right">'+right+'</div></div></main><script>function fit(){document.querySelector(".poster").style.zoom=Math.min(1,(innerWidth-32)/(841*96/25.4))}fit();addEventListener("resize",fit);</script></body></html>')
